 'resources':{label:'LEARNING CARDS',title:'Small prompts for better projects.',cards:[['RESEARCH','Start with reliable sources','Record citations as you work'],['DOCUMENT','Explain choices, not just code','Include methods, limitations and results'],['ACCESSIBILITY','Test beyond the happy path','Keyboard, contrast, labels and reduced motion']]},
 'legal':{label:'SITE NOTES',title:'Know what this prototype represents.',cards:[['DEMO','Some features are illustrative','Review the documented integration status'],['DATA','Forms do not use a site backend','Enquiry form prepares an email locally'],['REVIEW','Confirm policies before launch','Adapt legal copy to actual business practices']]}
