function HomeFAQ(){return <section className="section faq-section"><div className="container faq-layout"><div><SectionHeading eyebrow="COMMON QUESTIONS" title={<>A few things worth <span className="gradient-text">knowing.</span></>}>Clear answers help you decide what to build next.</SectionHeading><Link className="text-link" to="/contact">Still have a question? Contact us <ArrowUpRight size={16}/></Link></div><FAQ items={homeFaqs}/></div></section>}
function Pricing(){const[service,setService]=useState('Website development'),[pages,setPages]=useState(5),[design,setDesign]=useState(true),[cms,setCms]=useState(false),[support,setSupport]=useState(false);const total=5000+Math.max(0,pages-3)*800+(design?1800:0)+(cms?2500:0)+(support?1500:0);return <><PageIntro eyebrow="PRICING & ESTIMATES" title={<>Clear starting points. <span className="gradient-text">Thoughtful scope.</span></>} intro="Use the estimator to explore an illustrative website budget. A final quotation depends on confirmed requirements and deliverables."/><main className="container page-content"><FlashCardDeck variant="pricing"/><div className="pricing-layout"><div><span className="eyebrow">STARTING PRICES</span><h2>Choose a direction.</h2><p className="muted">Only the website starting price is defined here. Other categories require a project-specific discussion.</p><div className="pricing-cards">{[['STARTER','₹4,999','Focused first website',Globe],['BUSINESS','₹12,999','Growing business',Layers3],['PROFESSIONAL','₹19,999','More involved web presence',Rocket]].map(([n,p,l,I])=><article className={'pricing-card '+(n==='BUSINESS'?'popular':'')} key={n}>{n==='BUSINESS'&&<span className="popular-ribbon">Most Popular</span>}<span className="icon-tile"><I size={21}/></span><h3>{n}</h3><strong>{p}</strong><span>{l}</span><p>1 Year Free Domain Included*</p><Link className="text-link" to={'/contact?service=Website%20Development&budget='+encodeURIComponent(n+' '+p)}>Choose plan <ArrowRight size={15}/></Link></article>)}</div><p className="fine-print pricing-note">* “1 Year Free Domain Included” and all package inclusions require written confirmation. Hosting, renewal, maintenance, taxes and revisions may be separate unless agreed in writing.</p></div><aside className="estimator"><div className="estimator-head"><span className="icon-tile"><Layers3 size={21}/></span><div><span className="eyebrow">INTERACTIVE ESTIMATOR</span><h2>Website estimate</h2></div></div><label className="field-label">Project category<select value={service} onChange={e=>setService(e.target.value)}><option>Website development</option><option>Landing page</option><option>Business website</option><option>Portfolio website</option></select></label><div className="range-head"><label className="field-label">Estimated pages</label><b>{pages} pages</b></div><input className="range" type="range" min="1" max="15" value={pages} onChange={e=>setPages(+e.target.value)}/><div className="range-labels"><span>1 page</span><span>15 pages</span></div><div className="addon-list"><label><span><b>Enhanced visual design</b><small>Additional design refinement</small></span><input type="checkbox" checked={design} onChange={e=>setDesign(e.target.checked)}/></label><label><span><b>Content management setup</b><small>CMS integration allowance</small></span><input type="checkbox" checked={cms} onChange={e=>setCms(e.target.checked)}/></label><label><span><b>Support allowance</b><small>Initial support planning</small></span><input type="checkbox" checked={support} onChange={e=>setSupport(e.target.checked)}/></label></div><div className="estimate-total"><span>Illustrative estimate</span><strong>₹{total.toLocaleString('en-IN')}</strong><small>Not a quotation or confirmed price</small></div><Link className="button button-primary button-full" to={'/contact?service='+encodeURIComponent(service)+'&budget='+encodeURIComponent('Illustrative estimate ₹'+total.toLocaleString('en-IN'))}>Discuss this estimate <ArrowUpRight size={16}/></Link><p className="fine-print">Estimation formula is a planning aid only. Actual price may vary with integrations, content, complexity and requirements.</p></aside></div></main></>}
function Contact(){const loc=useLocation(),params=new URLSearchParams(loc.search);const[form,setForm]=useState({name:'',email:'',phone:'',service:params.get('service')||'',budget:params.get('budget')||'',description:'',method:'Email'}),[error,setError]=useState(''),[ready,setReady]=useState(false);function change(e){setForm({...form,[e.target.name]:e.target.value});setError('')}function submit(e){e.preventDefault();if(!form.name.trim()||!form.email.match(/^[^\s@]+@[^\s@]+\.[^\s@]+$/)||!form.description.trim()){setError('Please enter your name, a valid email address and a project description.');return}const subject=encodeURIComponent('Project enquiry — '+form.name);const body=encodeURIComponent(`Name: ${form.name}\nEmail: ${form.email}\nPhone: ${form.phone}\nService: ${form.service}\nBudget: ${form.budget}\nPreferred contact: ${form.method}\n\nProject description:\n${form.description}`);setReady(true);window.location.href=`mailto:${company.email}?subject=${subject}&body=${body}`}return <><PageIntro eyebrow="LET’S TALK" title={<>Let’s build something <span className="gradient-text">great together.</span></>} intro="Tell us about your idea, what you need and what success could look like. Start a conversation with Nuvora."/><main className="container page-content"><FlashCardDeck variant="contact"/><div className="contact-layout"><div className="contact-side"><span className="eyebrow">CONTACT NUVORA</span><h2>Good conversations make good projects.</h2><p>Share a little context and we can discuss the next step. The form opens your email app with the details prepared; it does not silently submit data to a server.</p><div className="contact-method"><span><Mail size={19}/></span><div><small>EMAIL</small><a href={'mailto:'+company.email}>{company.email}</a></div><ArrowUpRight size={16}/></div><div className="contact-method"><span><MessageCircle size={19}/></span><div><small>WHATSAPP</small><a href="https://wa.me/919959822236" target="_blank" rel="noreferrer">+91 99598 22236</a></div><ArrowUpRight size={16}/></div><div className="contact-method"><span><Globe size={19}/></span><div><small>INSTAGRAM</small><a href={company.instagram} target="_blank" rel="noreferrer">@nuvora_mind</a></div><ArrowUpRight size={16}/></div><div className="contact-method"><span><MapPin size={19}/></span><div><small>LOCATION</small><p>{company.address}</p></div></div></div><form className="contact-form" onSubmit={submit}><div className="form-heading"><span className="eyebrow">PROJECT ENQUIRY</span><h2>Tell us what you’re imagining.</h2><p>Fields marked * are required.</p></div><div className="form-grid"><label className="field-label">Your name *<input name="name" value={form.name} onChange={change} required placeholder="Name"/></label><label className="field-label">Email address *<input name="email" type="email" value={form.email} onChange={change} required placeholder="you@example.com"/></label><label className="field-label">Phone number<input name="phone" value={form.phone} onChange={change} placeholder="+91 …"/></label><label className="field-label">Service category<select name="service" value={form.service} onChange={change}><option value="">Choose a service</option>{allServices.map(s=><option key={s.slug}>{s.title}</option>)}</select></label><label className="field-label">Budget range<input name="budget" value={form.budget} onChange={change} placeholder="Optional"/></label><label className="field-label">Preferred contact<select name="method" value={form.method} onChange={change}><option>Email</option><option>Phone</option><option>WhatsApp</option></select></label><label className="field-label full-field">Project description *<textarea name="description" value={form.description} onChange={change} required rows="5" placeholder="What would you like to build? Include any goals, features or timelines you already have in mind."/></label></div>{error&&<p className="form-error" role="alert">{error}</p>}{ready&&<p className="form-note" role="status">Your email app should open with the enquiry details. If it doesn’t, email {company.email} directly.</p>}<button className="button button-primary" type="submit">Prepare enquiry email <Send size={16}/></button><p className="fine-print">No data is sent to a website backend by this demo form.</p></form></div></main></>}
function Login(){const[mode,setMode]=useState('login'),[show,setShow]=useState(false),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[note,setNote]=useState('');return <><PageIntro eyebrow="NUVORA PORTAL" title={<>Your work, <span className="gradient-text">in one place.</span></>} intro="Portal interface preview. Secure account services are not connected in this frontend demo."/><main className="container page-content auth-wrap"><FlashCardDeck variant="portal"/><form className="auth-card" onSubmit={e=>{e.preventDefault();setNote('Demo only: authentication is not connected. No credentials were saved or transmitted.')}}><div className="auth-emblem"><img src="/identity/nuvora-emblem.png" alt=""/></div><span className="eyebrow">WELCOME {mode==='login'?'BACK':'TO NUVORA'}</span><h2>{mode==='login'?'Sign in to your portal':'Create your account'}</h2><p>Demo interface · no real authentication</p>{mode==='signup'&&<label className="field-label">Full name<input required placeholder="Your name"/></label>}<label className="field-label">Email address<input type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com"/></label><label className="field-label">Password<div className="password-wrap"><input type={show?'text':'password'} required minLength="6" value={password} onChange={e=>setPassword(e.target.value)} placeholder="At least 6 characters"/><button type="button" onClick={()=>setShow(!show)}>{show?'Hide':'Show'}</button></div></label>{mode==='login'&&<button type="button" className="forgot-link" onClick={()=>setNote('Password recovery requires a configured authentication backend. Please contact Nuvora directly.')}>Forgot password?</button>}{note&&<div className="notice"><Lightbulb size={18}/><p>{note}</p></div>}<button className="button button-primary button-full">{mode==='login'?'Sign in (demo)':'Create account (demo)'} <ArrowRight size={16}/></button><div className="auth-switch">{mode==='login'?'New to Nuvora?':'Already have an account?'} <button type="button" onClick={()=>{setMode(mode==='login'?'signup':'login');setNote('')}}>{mode==='login'?'Sign up':'Sign in'}</button></div></form></main></>}
function Resources(){const[q,setQ]=useState('');const resources=[['Project idea starter','Academic projects','A checklist to narrow a project problem, audience and scope.',Lightbulb],['React learning path','Web development','A suggested sequence: components, state, routing, forms and deployment.',Code2],['AI/ML project planning','AI & Data Science','A planning outline for datasets, evaluation, limitations and documentation.',BrainCircuit],['Project documentation outline','Academic projects','Sections to consider: abstract, problem statement, methods, results and references.',BookOpen],['UI accessibility checklist','Design','Review keyboard navigation, focus states, labels, contrast and reduced motion.',ShieldCheck],['Dashboard design basics','Custom software','Think through hierarchy, key tasks, data meaning and empty states.',BarChart3]];const list=resources.filter(r=>r.join(' ').toLowerCase().includes(q.toLowerCase()));return <><PageIntro eyebrow="LEARN & EXPLORE" title={<>A resource hub for <span className="gradient-text">curious minds.</span></>} intro="A searchable collection of starting points for CSE, AI/ML, Data Science and web development learners."/><main className="container page-content"><FlashCardDeck variant="resources"/><label className="search-field resource-search"><Search size={18}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search resources, subjects or ideas…" aria-label="Search resources"/></label><div className="resource-grid">{list.map(([t,c,d,I],i)=><article className="resource-card" key={t}><span className="icon-tile"><I size={23}/></span><span className="eyebrow">{c}</span><h3>{t}</h3><p>{d}</p><span className="resource-sample">Nuvora learning note · Sample content</span><Link className="text-link" to="/contact">Discuss a project <ArrowUpRight size={15}/></Link></article>)}</div><div className="notice resource-notice"><BookOpen size={20}/><p>These are original starter notes, not external course links or downloadable academic papers. Verify sources and cite references in your own work.</p></div></main></>}
function Legal({privacy=false}){return <><PageIntro eyebrow={privacy?'PRIVACY':'TERMS'} title={privacy?<>Privacy, with <span className="gradient-text">clarity.</span></>:<>Clear terms. <span className="gradient-text">Better expectations.</span></>} intro="A plain-language starter policy for this website prototype."/><main className="container page-content legal-copy"><FlashCardDeck variant="legal"/><div className="notice"><Lightbulb size={18}/><p>This is a starter template and not legal advice. Have the final policy reviewed for your actual business practices before publishing.</p></div>{(privacy?[['Information you provide','If you contact Nuvora by email or another channel, information you choose to share may be processed to respond to your enquiry. This frontend demo does not send form submissions to a website backend.'],['Local preferences','The site may store your selected color theme in your browser so the interface remembers your preference.'],['Third-party services','Email, WhatsApp, Instagram and hosting providers have their own privacy terms when you choose to use them.'],['Questions','For privacy questions, contact info@nuvoramind.in.']]:[['Website content','Website information is provided for general informational purposes. Project scope, deliverables and pricing must be agreed separately.'],['Concept projects','Portfolio items labelled concepts or demos are illustrative and should not be treated as confirmed client work or production deployments.'],['No guarantee','No particular business, academic or technical outcome is guaranteed.'],['Contact','Questions about these terms can be sent to info@nuvoramind.in.']]).map(([h,p])=><section key={h}><h2>{h}</h2><p>{p}</p></section>)}</main></>}
function ProductsPage(){return <><PageIntro eyebrow="PRODUCTS" title={<>Digital products, <span className="gradient-text">clearly presented.</span></>} intro="Explore current product directions and concept previews. Capabilities are not represented as verified until approved product information is supplied."/><main className="container page-content"><section className="product-feature"><div className="product-art"><div className="product-window"><div className="window-dots"><i/><i/><i/></div><div className="product-ui-head"><span>NEXORAHUB</span><span className="concept-pill">CONCEPT PREVIEW</span></div><div className="product-ui-grid"><span/><span/><span/><span/><span/><span/></div><div className="product-ui-chart"><i/><i/><i/><i/><i/><i/><i/></div></div></div><div className="product-copy"><span className="eyebrow">FEATURED CONCEPT</span><h3>NexoraHub</h3><p>This page is a presentation placeholder for the NexoraHub product. Confirmed features, target users, availability, integrations and product screenshots are required before this can be described as a released product.</p><Link className="button button-primary" to="/contact?service=Product%20Enquiry">Ask about this product <ArrowUpRight size={16}/></Link></div></section><div className="product-mini-grid"><article id="ai-products"><BrainCircuit size={22}/><h3>AI product concepts</h3><p>Illustrative patterns for AI-assisted interfaces. No live AI connection is claimed.</p><span className="concept-pill">CONCEPT AREA</span></article><article id="saas-products"><Workflow size={22}/><h3>SaaS product concepts</h3><p>Example interface patterns for SaaS products, dashboards and workflows.</p><span className="concept-pill">CONCEPT AREA</span></article><article><Layers3 size={22}/><h3>Automation product concepts</h3><p>Early ideas for workflow automation with human review and clear boundaries.</p><span className="concept-pill">CONCEPT AREA</span></article></div></main></>}
function ProductDetail(){const{pathname}=useLocation();if(!pathname.endsWith('/nexorahub'))return <NotFound/>;return <><PageIntro eyebrow="PRODUCT CONCEPT" title={<>NexoraHub <span className="gradient-text">interface preview.</span></>} intro="A concept page awaiting verified product specifications from the owner."/><main className="container page-content"><div className="notice"><Lightbulb size={20}/><p>This is a concept preview only. Product functionality, availability, integrations, pricing and release status have not been verified in the supplied project materials.</p></div><div className="product-detail-grid"><article><h2>What is shown</h2><p>A visual direction for a potential product interface, using sample layout elements only.</p></article><article><h2>What needs confirmation</h2><p>Product purpose, user groups, real features, supported platforms, screenshots, release status and contact pathway.</p></article></div><Link className="button button-primary" to="/contact?service=Product%20Enquiry">Discuss product information <ArrowUpRight size={16}/></Link></main></>}
function AcademicProjectsPage({level='all'}){const title=level==='btech'?'B.Tech Projects':level==='mtech'?'M.Tech Projects':'Academic Technology Projects';return <><PageIntro eyebrow="ACADEMIC TECHNOLOGY" title={<>{title} <span className="gradient-text">with clear scope.</span></>} intro="Support may include problem framing, implementation guidance, documentation and demo preparation. Exact availability and scope must be agreed directly."/><main className="container page-content"><div className="notice"><ShieldCheck size={20}/><p>Academic support is intended to support learning and understanding. No marks, grades, publication, originality certification or academic outcomes are guaranteed. Follow your institution’s academic-integrity rules.</p></div><div className="academic-category-grid">{[['AI/ML & Data Science','Dataset planning, evaluation design, model explanation and responsible limitations.',BrainCircuit],['Web Applications','Frontend structure, interface flows, validation and responsive layout.',PanelTop],['Mobile Applications','Mobile-first user flows, interface concepts and cross-device planning.',Layers3],['Research & Documentation','Problem statement, methodology, evaluation, limitations and citation planning.',BookOpen],['Software & Automation','Requirements, workflow diagrams, implementation guidance and testing plans.',Workflow],['Demo & Presentation','Explainable demos, presentation structure and viva preparation guidance.',GraduationCap]].map(([name,desc,Icon])=><article className="academic-category-card" key={name}><span className="icon-tile"><Icon size={22}/></span><h3>{name}</h3><p>{desc}</p><Link className="text-link" to={'/contact?service='+encodeURIComponent('Academic Project')+'&budget='+encodeURIComponent(title)}>Discuss scope <ArrowUpRight size={15}/></Link></article>)}</div><div className="section-actions"><Link className="button button-ghost" to="/btech-projects">B.Tech projects</Link><Link className="button button-ghost" to="/mtech-projects">M.Tech projects</Link><Link className="button button-primary" to="/contact?service=Academic%20Project">Ask about availability</Link></div></main></>}
function NotFound(){return <main className="not-found container"><span className="eyebrow">404 / NOT FOUND</span><h1>This page took <span className="gradient-text">a different path.</span></h1><p>The page may have moved or the link may be out of date.</p><Link className="button button-primary" to="/">Back to home <ArrowRight size={16}/></Link></main>}
export default function App(){const[theme,setTheme]=useState(()=>{try{return localStorage.getItem('nuvora-theme')|| (window.matchMedia('(prefers-color-scheme: light)').matches?'light':'dark')}catch{return 'dark'}});const loc=useLocation();useEffect(()=>{document.documentElement.dataset.theme=theme;try{localStorage.setItem('nuvora-theme',theme)}catch{}},[theme]);useEffect(()=>{const path=loc.pathname;const titles={'/':'NuvoraMind | Technology, Products & Digital Solutions','/products':'Products | NuvoraMind','/academic-projects':'Academic Projects | NuvoraMind','/btech-projects':'B.Tech Projects | NuvoraMind','/mtech-projects':'M.Tech Projects | NuvoraMind','/services':'Services | NuvoraMind','/projects':'Projects | NuvoraMind','/process':'Our Process | NuvoraMind','/about':'About NuvoraMind','/contact':'Contact NuvoraMind','/pricing':'Pricing | NuvoraMind','/login':'Sign In | NuvoraMind','/signup':'Sign Up | NuvoraMind','/resources':'Resources | NuvoraMind','/privacy':'Privacy Policy | NuvoraMind','/terms':'Terms & Conditions | NuvoraMind'};document.title=titles[path]||((path.startsWith('/services/')?'Services':path.startsWith('/projects/')?'Project details':'NuvoraMind')+' | NuvoraMind');const desc=document.querySelector('meta[name="description"]');if(desc)desc.setAttribute('content',path==='/'?'NuvoraMind builds digital products, software solutions, AI systems, web and mobile applications, SaaS platforms and technology solutions.':'Explore '+document.title+'. Learn about Nuvora services, projects and ways to get in touch.');},[loc.pathname]);return <div className="app-shell"><Header theme={theme} setTheme={setTheme}/><Routes><Route path="/" element={<Home/>}/><Route path="/products" element={<ProductsPage/>}/><Route path="/products/:slug" element={<ProductDetail/>}/><Route path="/academic-projects" element={<AcademicProjectsPage/>}/><Route path="/btech-projects" element={<AcademicProjectsPage level="btech"/>}/><Route path="/mtech-projects" element={<AcademicProjectsPage level="mtech"/>}/><Route path="/services" element={<Services/>}/><Route path="/services/ai-ml-academic-projects" element={<ServiceDetail slug="ai-ml-academic-projects"/>}/><Route path="/services/:slug" element={<ServiceRouter/>}/><Route path="/projects" element={<Projects/>}/><Route path="/projects/:slug" element={<ProjectDetail/>}/><Route path="/process" element={<ProcessPage/>}/><Route path="/about" element={<About/>}/><Route path="/contact" element={<Contact/>}/><Route path="/pricing" element={<Pricing/>}/><Route path="/login" element={<Login/>}/><Route path="/signup" element={<Login/>}/><Route path="/resources" element={<Resources/>}/><Route path="/privacy" element={<Legal privacy/>}/><Route path="/privacy-policy" element={<Legal privacy/>}/><Route path="/terms" element={<Legal/>}/><Route path="/terms-and-conditions" element={<Legal/>}/><Route path="*" element={<NotFound/>}/></Routes><Footer/><AmbientFloaters/><FloatingLogo/><FloatingAssistant/></div>}
function ServiceRouter(){const{pathname}=useLocation();const slug=pathname.split('/').pop();return allServices.some(s=>s.slug===slug)?<ServiceDetail slug={slug}/>:<NotFound/>}
